import json


def diff(a, b):
    ops = []
    _diff(a, b, "$", ops)
    ops.sort()
    return ops


def _is_container(v):
    return isinstance(v, (dict, list))


def _same_type_equal(a, b):
    return type(a) is type(b) and a == b


def _render(v):
    return json.dumps(v, sort_keys=True)


def _diff(a, b, path, ops):
    if isinstance(a, dict) and isinstance(b, dict):
        for k in a:
            if k in b:
                _diff(a[k], b[k], f"{path}.{k}", ops)
            else:
                ops.append(f"- {path}.{k}: {_render(a[k])}")
        for k in b:
            if k not in a:
                ops.append(f"+ {path}.{k}: {_render(b[k])}")
    elif isinstance(a, list) and isinstance(b, list):
        common = min(len(a), len(b))
        for i in range(common):
            _diff(a[i], b[i], f"{path}[{i}]", ops)
        for i in range(common, len(a)):
            ops.append(f"- {path}[{i}]: {_render(a[i])}")
        for i in range(common, len(b)):
            ops.append(f"+ {path}[{i}]: {_render(b[i])}")
    elif _same_type_equal(a, b):
        pass
    else:
        ops.append(f"~ {path}: {_render(a)} -> {_render(b)}")
